import AppKit
struct Snippet:Codable,Equatable{var title:String;var text:String}
func validate(_ items:[Snippet])throws{if items.count>100||items.contains(where:{$0.title.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty||$0.title.count>80||$0.text.count>20000}){throw NSError(domain:"Use at most 100 snippets with nonempty titles <=80 characters and text <=20000 characters",code:1)}}
@MainActor final class Delegate:NSObject,NSApplicationDelegate{
 var item:NSStatusItem!;var snippets:[Snippet]=[];var writable=true
 let url=FileManager.default.urls(for:.applicationSupportDirectory,in:.userDomainMask)[0].appendingPathComponent("NetCoderMikeSnippets/snippets.json")
 func applicationDidFinishLaunching(_ notification:Notification){NSApp.setActivationPolicy(.accessory);do{if FileManager.default.fileExists(atPath:url.path){snippets=try JSONDecoder().decode([Snippet].self,from:Data(contentsOf:url));try validate(snippets)}}catch{writable=false;NSAlert(error:error).runModal()};item=NSStatusBar.system.statusItem(withLength:NSStatusItem.variableLength);item.button?.title="Snippets";menu()}
 func menu(){let m=NSMenu();for(i,s)in snippets.enumerated(){let entry=NSMenuItem(title:s.title,action:#selector(copy(_:)),keyEquivalent:"");entry.tag=i;entry.target=self;m.addItem(entry)};m.addItem(.separator());let add=NSMenuItem(title:"Add snippet…",action:#selector(add),keyEquivalent:"");add.target=self;add.isEnabled=writable;m.addItem(add);let quit=NSMenuItem(title:"Quit",action:#selector(quit),keyEquivalent:"");quit.target=self;m.addItem(quit);item.menu=m}
 @objc func copy(_ sender:NSMenuItem){guard snippets.indices.contains(sender.tag)else{return};NSPasteboard.general.clearContents();NSPasteboard.general.setString(snippets[sender.tag].text,forType:.string)}
 @objc func add(){let alert=NSAlert();alert.messageText="Add local snippet";alert.informativeText="Title and text. Copies happen only when you select a snippet.";alert.addButton(withTitle:"Save");alert.addButton(withTitle:"Cancel");let box=NSView(frame:NSRect(x:0,y:0,width:400,height:180));let title=NSTextField(frame:NSRect(x:0,y:145,width:400,height:25));title.placeholderString="Title";let text=NSTextView(frame:NSRect(x:0,y:0,width:400,height:130));text.font = .systemFont(ofSize:14);box.addSubview(title);box.addSubview(text);alert.accessoryView=box;guard alert.runModal() == .alertFirstButtonReturn else{return};do{let next=snippets+[Snippet(title:title.stringValue,text:text.string)];try validate(next);try FileManager.default.createDirectory(at:url.deletingLastPathComponent(),withIntermediateDirectories:true);try JSONEncoder().encode(next).write(to:url,options:.atomic);snippets=next;menu()}catch{NSAlert(error:error).runModal()}}
 @objc func quit(){NSApp.terminate(nil)}
}
@main struct LocalApp{@MainActor static func main()throws{if CommandLine.arguments.contains("--self-test"){let items=[Snippet(title:"Example",text:"hello\nworld")];try validate(items);let copy=try JSONDecoder().decode([Snippet].self,from:JSONEncoder().encode(items));precondition(copy==items);do{try validate([Snippet(title:"",text:"x")]);fatalError("Invalid title accepted")}catch{};print("Snippet schema and Codable round trip passed");return};let app=NSApplication.shared;let delegate=Delegate();app.delegate=delegate;app.run()}}
